<?php
declare(strict_types=1);require_once __DIR__.'/error_bootstrap.php';ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Strict');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');session_start();date_default_timezone_set('Asia/Tehran');
if(!file_exists(__DIR__.'/config.php')){header('Location:install.php');exit;}$c=require __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);require_once __DIR__.'/schema.php';ensure_product_schema($pdo);require_once __DIR__.'/admin_auth.php';ts_admin_schema($pdo);require_once __DIR__.'/backup_lib.php';ts_schedule_auto_backup($pdo);require_once __DIR__.'/store_lib.php';}catch(Throwable $e){ts_log_internal($e,'SYS-101');ts_html_fail('SYS-101',503,'index.php');}
$currentAdmin=ts_require_roles($pdo,['owner','manager']);
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
$msg='';$err='';
if((int)$pdo->query('SELECT COUNT(*) FROM delivery_zones')->fetchColumn()===0){$st=$pdo->prepare('INSERT INTO delivery_zones(name,fee,min_order,eta,active,sort_order) VALUES(?,?,?,?,1,0)');$st->execute(['بهارستان',(int)($c['delivery_fee']??0),0,'ارسال در اولین زمان ممکن']);}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){ts_html_fail('REQ-102',419,'index.php');}
 $a=(string)($_POST['action']??'');
 if($a==='save_settings'){
  $mode=(string)($_POST['manual_mode']??'auto');if(!in_array($mode,['auto','open','closed'],true))$mode='auto';
  $open=preg_match('/^\d{2}:\d{2}$/',(string)($_POST['open_time']??''))?(string)$_POST['open_time']:'08:00';
  $close=preg_match('/^\d{2}:\d{2}$/',(string)($_POST['close_time']??''))?(string)$_POST['close_time']:'23:00';
  $message=trim((string)($_POST['closed_message']??''));if($message==='')$message='سفارش‌گیری فعلاً بسته است.';
  set_store_setting($pdo,'manual_mode',$mode);set_store_setting($pdo,'open_time',$open);set_store_setting($pdo,'close_time',$close);set_store_setting($pdo,'closed_message',$message);$msg='تنظیمات فروشگاه ذخیره شد.';
 }
 if($a==='save_zone'){
  $id=max(0,(int)($_POST['id']??0));$name=trim((string)($_POST['name']??''));$fee=max(0,(int)($_POST['fee']??0));$min=max(0,(int)($_POST['min_order']??0));$eta=trim((string)($_POST['eta']??''));$active=isset($_POST['active'])?1:0;$sort=(int)($_POST['sort_order']??0);
  if($name==='')$err='نام محدوده را وارد کنید.';elseif($id){$st=$pdo->prepare('UPDATE delivery_zones SET name=?,fee=?,min_order=?,eta=?,active=?,sort_order=?,updated_at=NOW() WHERE id=?');$st->execute([$name,$fee,$min,$eta,$active,$sort,$id]);$msg='محدوده ویرایش شد.';}else{$st=$pdo->prepare('INSERT INTO delivery_zones(name,fee,min_order,eta,active,sort_order,created_at) VALUES(?,?,?,?,?,?,NOW())');$st->execute([$name,$fee,$min,$eta,$active,$sort]);$msg='محدوده جدید اضافه شد.';}
 }
 if($a==='delete_zone'){$id=max(0,(int)($_POST['id']??0));if($id)$pdo->prepare('DELETE FROM delivery_zones WHERE id=?')->execute([$id]);header('Location:admin_store.php');exit;}
}
$state=store_open_state($pdo);$zones=$pdo->query('SELECT * FROM delivery_zones ORDER BY sort_order,id')->fetchAll();
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تنظیمات فروشگاه</title><link rel="stylesheet" href="assets/style.css"><style>.wrap{max-width:950px;margin:20px auto;padding:0 14px}.zone{background:#fff;border:1px solid #e4ece6;border-radius:16px;padding:14px;margin:12px 0}.zone form{display:grid;grid-template-columns:2fr 1fr 1fr 2fr 90px;gap:8px;align-items:end}.status{padding:14px;border-radius:14px;margin-bottom:14px;font-weight:800}.status.open{background:#e5f7e9;color:#12602c}.status.closed{background:#fff0ee;color:#982d24}@media(max-width:750px){.zone form{grid-template-columns:1fr 1fr}.zone .wide{grid-column:1/-1}}</style></head><body><header class="top"><a class="brand" href="admin.php"><span class="logo">⚙️</span><span><b>تنظیمات فروشگاه</b><small>ساعت کاری و ارسال</small></span></a><a class="btn pale" href="admin.php">مدیریت اصلی</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="notice"><?=e($err)?></div><?php endif;?><div class="status <?=$state['open']?'open':'closed'?>"><?=$state['open']?'🟢 الان سفارش‌گیری باز است':'🔴 الان سفارش‌گیری بسته است'?></div><section class="panel"><h2>باز / بسته بودن فروشگاه</h2><form method="post" class="checkout"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="save_settings"><label>حالت<select name="manual_mode"><option value="auto" <?=$state['mode']==='auto'?'selected':''?>>خودکار طبق ساعت کاری</option><option value="open" <?=$state['mode']==='open'?'selected':''?>>دستی: باز</option><option value="closed" <?=$state['mode']==='closed'?'selected':''?>>دستی: بسته</option></select></label><label>شروع ساعت کاری<input type="time" name="open_time" value="<?=e($state['open_time'])?>"></label><label>پایان ساعت کاری<input type="time" name="close_time" value="<?=e($state['close_time'])?>"></label><label class="wide">پیام زمان تعطیلی<textarea name="closed_message"><?=e($state['message'])?></textarea></label><button class="btn wide">ذخیره تنظیمات</button></form></section><section class="panel"><div class="sectionhead"><div><h2>محدوده‌های ارسال</h2><p>هزینه، حداقل خرید و زمان تقریبی هر محدوده</p></div></div><?php foreach($zones as $z):?><div class="zone"><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="save_zone"><input type="hidden" name="id" value="<?=(int)$z['id']?>"><label>نام<input name="name" value="<?=e($z['name'])?>" required></label><label>هزینه (تومان)<input type="number" name="fee" min="0" value="<?=(int)$z['fee']?>"></label><label>حداقل خرید<input type="number" name="min_order" min="0" value="<?=(int)$z['min_order']?>"></label><label>زمان تقریبی<input name="eta" value="<?=e($z['eta'])?>"></label><label>فعال<input type="checkbox" name="active" value="1" <?=$z['active']?'checked':''?>></label><input type="hidden" name="sort_order" value="<?=(int)$z['sort_order']?>"><button class="btn wide">ذخیره</button></form><form method="post" onsubmit="return confirm('این محدوده حذف شود؟')" style="margin-top:7px"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="delete_zone"><input type="hidden" name="id" value="<?=(int)$z['id']?>"><button class="remove">حذف محدوده</button></form></div><?php endforeach;?><div class="zone"><h3>+ محدوده جدید</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="save_zone"><input type="hidden" name="id" value="0"><label>نام<input name="name" required placeholder="مثلاً بهارستان فاز ۱"></label><label>هزینه<input type="number" name="fee" min="0" value="0"></label><label>حداقل خرید<input type="number" name="min_order" min="0" value="0"></label><label>زمان تقریبی<input name="eta" placeholder="مثلاً ۳۰ تا ۴۵ دقیقه"></label><label>فعال<input type="checkbox" name="active" value="1" checked></label><input type="hidden" name="sort_order" value="0"><button class="btn wide">اضافه کن</button></form></div></section></main></body></html>